+      <StatusChip
+        icon={<LuFileWarning />}
+        label={label}
+        onClick={onOpen}
+        severity={hasError ? "error" : "warning"}
+      />
+      <DAGWarningsModal
+        deactivatedMessage={deactivatedMessage}
+        error={error}
+        importError={importError}
+        onClose={onClose}
+        open={open}
+        warnings={warnings}
+      />
+    </>
+  );
+};

